  @Property({ type: t.text, nullable: true, lazy: true })
  perex?: string;

  @Property({ type: t.decimal, precision: 8, scale: 2, nullable: true })
  price?: number;

  @Formula(alias => `${alias}.price * 1.19`)
  priceTaxed?: string;

  @Property({ type: t.double, nullable: true })
